#!/bin/sh
# Notice hook for Codex. Generated by Notice; reinstalling hooks rewrites it.
#
# Notice only records what Codex does; approving commands is left to Codex.
# So the hook forwards every event and always lets the call through. It prints
# nothing: on PreToolUse Codex rejects "continue", "stopReason" and
# "suppressOutput" as unsupported fields and logs the hook as failed.
TOKEN_FILE=__TOKEN_FILE__
URL=__URL__

[ -r "$TOKEN_FILE" ] || exit 0
PAYLOAD="$(cat)"
TOKEN="$(cat "$TOKEN_FILE")"
printf '%s' "$PAYLOAD" | /usr/bin/curl -sS --connect-timeout 1 --max-time 3 \
  -H "Content-Type: application/json" \
  -H "X-Notice-Token: $TOKEN" \
  --data-binary @- \
  -o /dev/null \
  "$URL" 2>/dev/null
exit 0
